mapper.select:
select count(a.ContractID) as normallyTotal
from (
	select cc.ContractID from cr_contractbasic cc where  cc.MainOrgID = #{orgId}  and cc.LogicDel =0

		and cc.CreatedDate between #{startTime} and #{endTime}		

) as a
where NOT EXISTS(select 1 from cr_contractcase ccc where a.ContractID=ccc.ContractID and ccc.LogicDel=0)
